class Solution {
public:
    int maximumTastiness(std::vector<int>& price, int k) {
        std::sort(price.begin(), price.end());
        int lo = 0, hi = price.back() - price.front();
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            int cnt = 1, last = price[0];
            for (size_t i = 1; i < price.size(); ++i) {
                if (price[i] >= last + mid) {
                    cnt++;
                    last = price[i];
                }
            }
            if (cnt >= k) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
};

class Solution {
    public int maximumTastiness(int[] price, int k) {
        java.util.Arrays.sort(price);
        int lo = 0, hi = price[price.length - 1] - price[0];
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            int cnt = 1, last = price[0];
            for (int i = 1; i < price.length; i++) {
                if (price[i] >= last + mid) {
                    cnt++;
                    last = price[i];
                }
            }
            if (cnt >= k) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
}

var maximumTastiness = function(price, k) {
    price.sort((a, b) => a - b);
    let lo = 0, hi = price[price.length - 1] - price[0];
    while (lo < hi) {
        const mid = Math.floor((lo + hi + 1) / 2);
        let cnt = 1, last = price[0];
        for (let i = 1; i < price.length; i++) {
            if (price[i] >= last + mid) {
                cnt++;
                last = price[i];
            }
        }
        if (cnt >= k) lo = mid;
        else hi = mid - 1;
    }
    return lo;
};
